{
  "findings": [
    {
      "check_id": "CKV_GCP_117",
      "title": "Ensure basic roles are not used at project level",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "HIGH",
      "explanation": "The 'roles/editor' role is a basic role that grants broad permissions, including permissions that may not be necessary for the users. Using basic roles at the project level increases the risk of privilege escalation and accidental or malicious changes."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  role    = \"roles/viewer\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}",
  "fix_summary": "Replaced the 'roles/editor' role with 'roles/viewer' to limit permissions to read-only access, reducing the risk of privilege escalation and unauthorized changes."
}
